REPLACE INTO ?:page_descriptions (page_id, page, description, lang_code) VALUES('7', 'Производители', '', 'ru');
REPLACE INTO ?:page_descriptions (page_id, page, description, lang_code) VALUES('40', 'Ergom', '<p>Ergom — основной бренд каталога. Он объединяет базовую линейку для ежедневного профессионального применения: надёжный инструмент и оборудование, рассчитанные на длительную нагрузку.</p><!--CUT--><p><b>Почему выбирают Ergom:</b><ul><li>Широкий ассортимент для ремонта, сборки и обслуживания.</li><li>Прочный корпус и износостойкие детали.</li><li>Документация и технические характеристики для каждой позиции.</li></ul><p>Ergom — рекомендуемый выбор, когда важно сочетание цены и надёжности.</p>', 'ru');
REPLACE INTO ?:page_descriptions (page_id, page, description, lang_code) VALUES('41', 'Ergom PRO', '<p>Ergom PRO — профессиональная линейка бренда. Она рассчитана на ежедневную работу под высокой нагрузкой, на сервисные бригады и на пользователей, которые не могут позволить себе простой.</p><!--CUT--><p><b>Особенности Ergom PRO:</b><ul><li>Усиленный корпус и увеличенный ресурс.</li><li>Более высокая точность и стабильная работа в тяжёлых условиях.</li><li>Расширенная гарантия и доступность запасных частей.</li></ul>', 'ru');
REPLACE INTO ?:page_descriptions (page_id, page, description, lang_code) VALUES('42', 'Ergom Safety', '<p>Ergom Safety — линейка средств индивидуальной защиты и охраны труда. Все позиции сертифицированы и подобраны так, чтобы снизить риск травмы при работе.</p><!--CUT--><p><b>Ассортимент линейки:</b><ul><li>Защитные перчатки, очки и каски.</li><li>Спецодежда повышенной видимости.</li><li>Изолирующие и защитные средства.</li></ul><p>Все позиции этой линейки помечены в каталоге бейджем <b>Safety</b>, поэтому их можно отобрать одним фильтром.</p>', 'ru');
REPLACE INTO ?:page_descriptions (page_id, page, description, lang_code) VALUES('43', 'Ergom OEM', '<p>Ergom OEM — линейка собственной торговой марки. Она производится по техническому заданию заказчика и используется для розничных сетей и корпоративных программ.</p><!--CUT--><p><b>Возможности OEM:</b><ul><li>Собственный брендинг и упаковка.</li><li>Адаптация линейки под ассортимент заказчика.</li><li>Поставка партиями с отдельными карточками товаров.</li></ul>', 'ru');
